/**
 * The booking voucher (0068) — what a code is worth right now.
 *
 * ─────────────────────────────────────────────────────────────────────────
 *  EVERY BOOKING CARRIES ONE, ON EVERY PLAN.
 *
 *  A code like R237-4K7Q-M9DX is generated by the database when the booking
 *  is created, and its QR opens /v/<code>. It proves the booking at the door
 *  and carries the deposit to the bill. It is valid from TWO HOURS BEFORE the
 *  booking to the END OF THAT DAY (Africa/Douala), redeemed once, by staff of
 *  that restaurant only (redeem_reservation_voucher locks the row).
 *
 *  Status is DERIVED, never stored: a booking cancelled with its deposit
 *  refunded reads "refunded", a no-show reads "expired" — nothing has to run
 *  to keep the two in step. The database repeats these rules when redeeming;
 *  this copy is what every screen shows.
 * ─────────────────────────────────────────────────────────────────────────
 */

import { DISPLAY_TZ } from "@/lib/format/datetime";

export type VoucherState =
  | "valid"
  | "tooEarly"
  | "used"
  | "expired"
  | "cancelled"
  | "refunded"
  | "notConfirmed";

/** How long before the booking the voucher opens. */
export const VOUCHER_OPENS_BEFORE_MIN = 120;

const CODE = /^R237-[ACDEFGHJKLMNPQRTUVWXY34679]{4}-[ACDEFGHJKLMNPQRTUVWXY34679]{4}$/;

/** Upper-cases, trims, and restores the dashes a person may have skipped. */
export function normaliseVoucherCode(raw: string): string {
  const compact = raw.toUpperCase().replace(/[^A-Z0-9]/g, "");
  if (compact.length === 12 && compact.startsWith("R237")) {
    return `R237-${compact.slice(4, 8)}-${compact.slice(8)}`;
  }
  return raw.trim().toUpperCase();
}

export function isVoucherCode(raw: string): boolean {
  return CODE.test(normaliseVoucherCode(raw));
}

/** The end of the booking's calendar day in the display zone (UTC+1, no DST). */
export function endOfBookingDay(reservedFor: string | Date): Date {
  const at = typeof reservedFor === "string" ? new Date(reservedFor) : reservedFor;
  const day = new Intl.DateTimeFormat("en-CA", {
    timeZone: DISPLAY_TZ,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(at);
  const midnight = new Date(`${day}T00:00:00+01:00`);
  return new Date(midnight.getTime() + 24 * 60 * 60_000);
}

export function voucherWindow(reservedFor: string | Date): { opensAt: Date; closesAt: Date } {
  const at = typeof reservedFor === "string" ? new Date(reservedFor) : reservedFor;
  return {
    opensAt: new Date(at.getTime() - VOUCHER_OPENS_BEFORE_MIN * 60_000),
    closesAt: endOfBookingDay(at),
  };
}

export function voucherState(
  booking: {
    status: string;
    reservedFor: string;
    redeemedAt: string | null;
    depositPaid: boolean;
  },
  now: Date = new Date(),
): VoucherState {
  if (booking.redeemedAt) return "used";
  if (booking.status === "cancelled") return booking.depositPaid ? "refunded" : "cancelled";
  if (booking.status === "no_show") return "expired";
  if (booking.status === "completed") return "used";
  const { opensAt, closesAt } = voucherWindow(booking.reservedFor);
  if (now.getTime() >= closesAt.getTime()) return "expired";
  if (booking.status !== "confirmed" && booking.status !== "seated") return "notConfirmed";
  if (now.getTime() < opensAt.getTime()) return "tooEarly";
  return "valid";
}

/** What the voucher takes off the bill: only a deposit actually paid online or at the counter. */
export function voucherCredit(booking: { depositPaid: boolean; depositAmount: number; depositPercent: number }): number {
  if (!booking.depositPaid || booking.depositPercent > 0) return 0;
  return Math.max(0, Math.round(booking.depositAmount));
}
